CALL {
  MATCH (e:Event)-[:DETECTED_BY]->(c:Camera)-[:LOCATED_AT]->(:Location {name: 'Gate_MainEntrance'}) 
  WHERE e.timestamp_utc >= '2025-12-08T00:00:00Z' AND e.timestamp_utc < '2025-12-09T00:00:00Z'
  WITH substring(e.timestamp_utc, 0, 13) + ':00:00Z' AS hour, count(*) AS n
  RETURN hour, n
  ORDER BY n DESC LIMIT 5
}
WITH COLLECT({hour: hour, count: n}) AS gate_activity
CALL {
  MATCH (ch:CrowdHour)-[:AT_CAMERA]->(c:Camera)-[:LOCATED_AT]->(:Location {name: 'Keynote_Hall'})
  WHERE ch.hour_utc >= '2025-12-08T00:00:00Z' AND ch.hour_utc < '2025-12-09T00:00:00Z'
  RETURN ch.hour_utc AS hour, max(ch.peak_hc) AS peak_attendance
}
WITH gate_activity, COLLECT({hour: hour, peak_attendance: peak_attendance}) AS keynote_attendance
CALL {
  MATCH (ch:CrowdHour)-[:AT_CAMERA]->(c:Camera)-[:LOCATED_AT]->(:Location {name: 'Food_Court'})
  WHERE ch.hour_utc >= '2025-12-08T00:00:00Z' AND ch.hour_utc < '2025-12-09T00:00:00Z'
  RETURN ch.hour_utc AS hour, avg(ch.avg_hc) AS avg_density
}
WITH gate_activity, keynote_attendance, COLLECT({hour: hour, avg_density: avg_density}) AS food_court_density
CALL {
  MATCH (ch:CrowdHour)-[:AT_CAMERA]->(c:Camera)-[:LOCATED_AT]->(:Location {name: 'DemoBooth_NVIDIA'})
  WHERE ch.hour_utc >= '2025-12-08T00:00:00Z' AND ch.hour_utc < '2025-12-09T00:00:00Z'
  RETURN sum(ch.event_count) AS n, 'NVIDIA' AS booth
}
WITH gate_activity, keynote_attendance, food_court_density, COLLECT({booth: booth, count: n}) AS nvidia_activity
CALL {
  MATCH (ch:CrowdHour)-[:AT_CAMERA]->(c:Camera)-[:LOCATED_AT]->(:Location {name: 'DemoBooth_Intel'})
  WHERE ch.hour_utc >= '2025-12-08T00:00:00Z' AND ch.hour_utc < '2025-12-09T00:00:00Z'
  RETURN sum(ch.event_count) AS n, 'Intel' AS booth
}
RETURN gate_activity, keynote_attendance, food_court_density, nvidia_activity, COLLECT({booth: booth, count: n}) AS intel_activity
